32: const C = {
33:   reset: '\x1b[0m',
34:   bold: '\x1b[1m',
35:   green: '\x1b[32m',
36:   red: '\x1b[31m',
37:   cyan: '\x1b[36m',
38:   gray: '\x1b[90m'
39: };
